-- ============================================================================
-- EFFICIENTIA - DATALOAD: FROTA, PARCEIROS E DOMÍNIOS
-- ============================================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

-- Desativar triggers temporariamente para máxima performance
SET session_replication_role = 'replica';

BEGIN;

-- 5. CAVALOS MECÂNICOS (120 registros)
ON CONFLICT (id) DO NOTHING;

-- 6. CARRETAS BOIADEIRAS (120 registros)
ON CONFLICT (id) DO NOTHING;

-- 7. FAZENDAS FORNECEDORAS (100 registros)
ON CONFLICT (id) DO NOTHING;

-- 8. UNIDADES FRIGORÍFICAS (25 registros)
ON CONFLICT (id) DO NOTHING;

-- 9. DOMÍNIO DE MOTIVOS DE PARADA (5 registros)
ON CONFLICT (codigo) DO UPDATE SET descricao = EXCLUDED.descricao;

-- 10. DOMÍNIO DE ANOMALIAS (15 registros)
ON CONFLICT (tipo_etapa, codigo) DO UPDATE SET descricao = EXCLUDED.descricao;


COMMIT;

-- Reativar triggers do sistema
SET session_replication_role = 'origin';
